cd /tmp; python3 - <<'EOF'
import zipfile, re
z=zipfile.ZipFile('logic.jar')
s=b'(pkg\\.github|maven\\.pkg|GITHUB_TOKEN|swcodeGpr|gpr\\.user|gpr\\.key|github)'
pat=re.compile(s.encode(), re.I)
hits={}
for n in z.namelist():
    if n.endswith(('.class','.properties','.kts','.txt','.xml','.json')):
        try: d=z.read(n)
        except Exception: continue
        m=pat.findall(d)
        if m: hits[n]=list(set(x.decode() for x in m))[:5]
for k,v in hits.items():
    print(k, v)
print("total", len(hits))
EOF
